import{_ as t,o as a,c as n,a0 as i}from"./chunks/framework.BXmxXpv-.js";const h=JSON.parse('{"title":"","titleTemplate":"UESTC","description":"Intelligent Computing Systems Laboratory at UESTC, researching intelligent computing, IoT, wireless embedded systems, edge intelligence, sensing and system security.","frontmatter":{"layout":"home","titleTemplate":"UESTC","description":"Intelligent Computing Systems Laboratory at UESTC, researching intelligent computing, IoT, wireless embedded systems, edge intelligence, sensing and system security.","hero":{"name":"Intelligent Computing Systems\\nLaboratory","tagline":"Next-generation Intelligent Systems Exploration","image":{"src":"/nise-logo.svg","alt":"ICSLab"}}},"headers":[],"relativePath":"index.md","filePath":"en/index.md","lastUpdated":1783607232000}'),o={name:"index.md"};function r(s,e,l,d,c,m){return a(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="news" tabindex="-1">News <a class="header-anchor" href="#news" aria-label="Permalink to &quot;News&quot;">​</a></h2><h3 id="july-2026" tabindex="-1">July 2026 <a class="header-anchor" href="#july-2026" aria-label="Permalink to &quot;July 2026&quot;">​</a></h3><ul><li>Congratulations to our team on the acceptance of <strong><a href="/publication">Hades: A Hardware-Resident Substrate for Energy Admission in Intermittent Computing</a></strong> by <strong>MICRO 2026</strong>. This is the first MICRO paper from a university in Western China.</li><li>Congratulations to our team: <strong><a href="/publication">Speak and Be Known: Authenticating Users via Ear Canal Deformation on Earbuds</a></strong> was published in <strong>TMC 2026</strong>.</li></ul><h3 id="may-2026" tabindex="-1">May 2026 <a class="header-anchor" href="#may-2026" aria-label="Permalink to &quot;May 2026&quot;">​</a></h3><ul><li>Congratulations to our team on the acceptance of <strong><a href="/publication">μMan: Towards Device-Agnostic Power Management for Battery-free IoT</a></strong> by <strong>SenSys 2026</strong>.</li></ul><h3 id="march-2026" tabindex="-1">March 2026 <a class="header-anchor" href="#march-2026" aria-label="Permalink to &quot;March 2026&quot;">​</a></h3><ul><li>Congratulations to our team: <strong><a href="/publication">Remote Intermittency Control for RF-powered Devices via Backscatter Communication</a></strong> was published in <strong>TMC 2026</strong>.</li></ul><p>... <a href="/news">See all news</a></p><h2 id="about-us" tabindex="-1">About Us <a class="header-anchor" href="#about-us" aria-label="Permalink to &quot;About Us&quot;">​</a></h2><p>The Intelligent Computing Systems Laboratory is affiliated with the School of Computer Science and Engineering, University of Electronic Science and Technology of China (UESTC). Established in January 2018, the lab conducts fundamental research and system development in wireless systems and security, passive systems, RFID technology, network and system security, intelligent information processing, data mining and recommendation, and intelligent video analysis. We study how intelligent computing systems interact with the physical world, with a measured focus on sensing, communication, edge intelligence, and wireless embedded systems that can support embodied intelligent applications. The team currently includes 1 professor, 1 associate professor, and nearly 30 master&#39;s and doctoral students. Over the past five years, we have undertaken multiple projects funded by the National Natural Science Foundation of China, National Key R&amp;D Programs, and National Science and Technology Support Programs.</p><p>The team has achieved a series of research outcomes in passive wireless sensing IoT systems, wireless embedded systems, and intelligent information processing. We have built practical systems and application demonstrations for structural health monitoring, wearable medical devices, and remote health monitoring. Our members have published over 120 papers in ACM/IEEE Transactions journals and top international academic conferences. The laboratory is equipped with comprehensive R&amp;D equipment, system software, application software, and design tools, supporting an end-to-end R&amp;D chain from sensing front-end design, communication protocols and systems, intelligent information processing, cloud systems, to network security.</p><h2 id="main-research-areas" tabindex="-1">Main Research Areas <a class="header-anchor" href="#main-research-areas" aria-label="Permalink to &quot;Main Research Areas&quot;">​</a></h2><ul><li><strong>IoT Edge Architecture and Intelligent Computing</strong>: Lightweight edge intelligent algorithms and chip design for embodied intelligence, edge-cloud collaborative computing architecture and task offloading strategies, mobile analysis, and machine learning applications at the edge.</li><li><strong>Embodied Intelligent Sensing and Interaction</strong>: Intelligent perception of the physical world, cognitive mechanisms of image and visual information computing, passive wireless sensing systems.</li><li><strong>Swarm Collaborative Intelligence and Communication</strong>: Communication technologies for swarm collaboration, distributed intelligence and collaborative decision-making, wireless systems, and network security.</li><li><strong>Intelligent Information Processing and Applications</strong>: Data mining and recommendation systems, intelligent data analysis, prototype systems, and application demonstrations.</li></ul><h2 id="representative-research-projects" tabindex="-1">Representative Research Projects <a class="header-anchor" href="#representative-research-projects" aria-label="Permalink to &quot;Representative Research Projects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Program</th><th>Project</th><th>Period</th></tr></thead><tbody><tr><td>NSFC General Program</td><td>Theory and key technologies of IoT wireless bus</td><td>2026-2029</td></tr><tr><td>Industry Collaboration</td><td>Research and development of integrated technologies for a cloud-edge-device intelligent precision milling and planing system</td><td>2026-2028</td></tr><tr><td>NSFC General Program</td><td>Distributed large-scale graph data stream computing methods with cloud-edge integration</td><td>2025-2028</td></tr><tr><td>Industry Collaboration</td><td>Mechanism study and precision resuscitation of extracorporeal cardiac compression based on dynamics</td><td>2024-2025</td></tr><tr><td>Internal R&amp;D Project</td><td>Research on long-range ultra-low-power wireless communication chips</td><td>2023-2026</td></tr><tr><td>NSFC General Program</td><td>Mechanism research and translation of a thrombosis-inflammation model for early diagnosis and risk stratification of acute aortic dissection based on multi-omics temporal graph neural networks</td><td>2023-2025</td></tr><tr><td>NSFC Joint Fund Key Program</td><td>Threat monitoring and dynamic adaptive defense for safety-critical aviation intelligent manufacturing</td><td>2022-2025</td></tr><tr><td>National Key R&amp;D Program of China</td><td>Key technologies for on-demand privacy data desensitization and evaluation</td><td>2021-2024</td></tr></tbody></table>',15)])])}const u=t(o,[["render",r]]);export{h as __pageData,u as default};
